-- Backfill (run once, after sql/2026-10-29-signing-waves.sql). Idempotent: INSERT OR IGNORE, and
-- only rows without a wave are set. Harry, 29.10.2026: waves are the PDF date, as in the РИК; every
-- past date so far was sent. Only past dates are closed here: a wave of today (or later) is never
-- closed by a backfill, only by „Изпратена на РИК“. The first version also closed 29.10 (the day it
-- ran) as 'backfill-2026-10-29', which had not gone to the РИК; that was undone in prod on 29.10.
-- Each wave row is written only for a date before today (date('now') is UTC, never after the Sofia
-- date), and rows get a wave only when that wave row exists, so a re-run can't close today.
-- Withdrawn and duplicate rows get the wave too (they are left out of the ZIP and tables anyway).

INSERT OR IGNORE INTO signing_waves (id, issue_date, closed_at, closed_by) SELECT 'backfill-2026-10-19', '2026-10-19', '2026-10-19T20:59:00.000Z', 'backfill' WHERE '2026-10-19' < date('now');
UPDATE signups SET designation_wave_id = 'backfill-2026-10-19' WHERE designation_wave_id IS NULL AND designation_number IS NOT NULL AND (CASE WHEN designation_issued_at LIKE '__.__.____' THEN substr(designation_issued_at, 7, 4) || '-' || substr(designation_issued_at, 4, 2) || '-' || substr(designation_issued_at, 1, 2) WHEN designation_issued_at LIKE '____-__-__%' THEN substr(designation_issued_at, 1, 10) ELSE '' END) = '2026-10-19' AND EXISTS (SELECT 1 FROM signing_waves WHERE id = 'backfill-2026-10-19' AND issue_date < date('now'));
UPDATE partner_people SET designation_wave_id = 'backfill-2026-10-19' WHERE designation_wave_id IS NULL AND designation_number IS NOT NULL AND (CASE WHEN designation_issued_at LIKE '__.__.____' THEN substr(designation_issued_at, 7, 4) || '-' || substr(designation_issued_at, 4, 2) || '-' || substr(designation_issued_at, 1, 2) WHEN designation_issued_at LIKE '____-__-__%' THEN substr(designation_issued_at, 1, 10) ELSE '' END) = '2026-10-19' AND EXISTS (SELECT 1 FROM signing_waves WHERE id = 'backfill-2026-10-19' AND issue_date < date('now'));
